/**
 * Markup for one rail glyph.
 * @param {string} name - glyph key (home, schedules, plugins, more, settings, agent, dot).
 * @param {boolean} [selected] - use the filled/emphasis twin when one exists.
 * @returns {string} inline SVG markup, or an empty string for an unknown glyph.
 */
function chatgptRailGlyph(name, selected) {
  const glyph = CHATGPT_RAIL_GLYPHS[name]
  if (glyph === undefined) return ''
  return selected === true ? glyph.selected : glyph.default
}
